function mashaerAt(la,lo){if(typeof la!=="number")return null;for(const k of ["jamarat","mina","muzdalifah","arafat"]){const z=MASHAER[k];const km=kmBetween(la,lo,z.c[0],z.c[1]);if(km<=z.r)return Object.assign({k,km},z)}return null}
