function campNoIn(t){const m=String(t||"").replace(/[٠-٩]/g,d=>"٠١٢٣٤٥٦٧٨٩".indexOf(d)).match(/([0-9]{1,3}|[A-Za-z])\s*\/\s*([0-9]{1,4})/);return m?(m[1]+"/"+m[2]).toUpperCase():""}
function mashaerNow(){const r=state.real;return r&&typeof r.la==="number"?mashaerAt(r.la,r.lo):null}
function mashaerKey(t){const n=normAr(t||"");return /جمرات/.test(n)?"jamarat":/مزدلف/.test(n)?"muzdalifah":/عرف/.test(n)?"arafat":/(^|\s|ب|في)(مني|منا)(\s|$)/.test(n)?"mina":""}
