function hijriDM(d){try{const p=new Intl.DateTimeFormat("en-u-ca-islamic-umalqura-nu-latn",{day:"numeric",month:"numeric"}).formatToParts(d||new Date());return{d:+p.find(x=>x.type==="day").value,m:+p.find(x=>x.type==="month").value}}catch(_){return null}}
function hajjDay(){if(state.hajjDayTest)return state.hajjDayTest;const h=hijriDM();return h&&h.m===12&&h.d>=8&&h.d<=13?h.d:null}
const HAJJ_DAYS={8:{t:"يوم التروية (8 ذو الحجة)",kb:"يوم التروية في منى"},9:{t:"يوم عرفة (9 ذو الحجة)",kb:"يوم عرفة والوقوف بعرفة"},10:{t:"يوم النحر (10 ذو الحجة)",kb:"أعمال يوم النحر وترتيبها"},11:{t:"أول أيام التشريق (11 ذو الحجة)",kb:"رمي الجمرات في أيام التشريق"},12:{t:"ثاني أيام التشريق (12 ذو الحجة)",kb:"التعجل والتأخر ومغادرة منى"},13:{t:"ثالث أيام التشريق (13 ذو الحجة)",kb:"رمي الجمرات في أيام التشريق"}};
