function schedPick(rows,q){if(!rows.length)return null;const n=" "+kbNorm(q||"").trim().replace(/ (لل|ل)(?=\S{3})/g," الي ")+" ";const to=((n.match(/ الي (\S+)/)||[])[1]||"").replace(/^(ال|لل)/,"");const fr=((n.match(/ من (\S+)/)||[])[1]||"").replace(/^(ال)/,"");const hd=hajjDay();
  const sc=x=>{const w=normAr(x.w);const [a,b]=[w.split(" الي ")[0]||"",w.split(" الي ")[1]||""];let v=0;if(to&&b.includes(to))v+=3;if(fr&&a.includes(fr))v+=3;if(hd&&x.h===hd)v+=1;if(hd&&x.h<hd)v-=1;return v};
  return rows.slice().sort((x,y)=>sc(y)-sc(x))[0]}
