      if(place==="gate"&&gate){const q=normAr(gate.replace(/[؟?.!]/g,""));const g=(LAND[state.site]||[]).find(x=>normAr(x[0]).includes(q)||q.split(" ").every(w=>normAr(x[0]).includes(w)));
        if(!g){card(head(ICON.map,"نقطة اللقاء","")+`<div>لا أعرف بابا بهذا الاسم. الأبواب التي أعرفها: ${esc((LAND[state.site]||[]).slice(0,8).map(x=>x[0]).join("، "))}.</div>`);return{known:false}}
        const me=state.real&&typeof state.real.la==="number"?Math.round(kmBetween(state.real.la,state.real.lo,g[1],g[2])*1000):null;state.lastDest=g[0];state.lastDist=me||150;state.meet={place:g[0],la:g[1],lo:g[2],t:Date.now(),by:profile.name||"ضيف",g:profile.gender||""};if(state.pushPresence)try{state.pushPresence()}catch(_){}
        log("nav","نقطة لقاء يختارها الضيف",g[0]+" · أرسلت إلى "+(names.join("، ")||"لا أحد متصل"));
        card(head(ICON.map,"نقطة اللقاء: "+esc(g[0]),names.length?"أرسلت إلى "+esc(names.join("، "))+" في كنف":"لا أحد متصل الآن")+`<dl class="kv">${me!==null?`<dt>أنت</dt><dd>${me<1000?me+" م، نحو "+walk(me)+" دقيقة":(me/1000).toFixed(1)+" كم"}</dd>`:""}${live.map(l=>`<dt>${esc(clean(l.name))}</dt><dd>${typeof l.la==="number"?Math.round(kmBetween(l.la,l.lo,g[1],g[2])*1000)+" م":"وصلته النقطة، ولم يصلني موقعه بعد"}</dd>`).join("")}</dl><div class="acts"><button class="primary" data-say="ابدأ الإرشاد إلى نقطة اللقاء">دلني إليها</button></div>`);return{meeting_point:g[0],lat:g[1],lon:g[2],sent_to:names}}
      const me=state.real&&typeof state.real.la==="number"?{name:"أنت",la:state.real.la,lo:state.real.lo}:null;const withPos=live.filter(l=>typeof l.la==="number").map(l=>({name:clean(l.name),la:l.la,lo:l.lo,g:l.g}));const all=(me?[me]:[]).concat(withPos);
