      const secCar=`<div class="sec">${en?"If you come by car, the nearest Haram parking areas:":"إن جئت بسيارتك، أقرب مواقف الحرم:"}</div><div class="steps">${parks.map(parkRow).join("")}</div><div style="font-size:.78rem;color:var(--muted)">${en?"Shuttle buses run from the main lots to the Haram in busy seasons; check at the lot on arrival.":"من المواقف الرئيسية يعمل نقل ترددي إلى المسجد في المواسم، وتحقق من تشغيله عند وصولك."}</div>`;
      const secRide=`<div class="sec">${near?(en?"Or request a ride by app from here:":"أو اطلب سيارة أجرة بالتطبيق من هنا:"):(en?"Or request a ride by app straight to the Haram:":"أو اطلب سيارة أجرة بالتطبيق إلى المسجد الحرام مباشرة:")}</div><div class="acts">${btn(near?"https://m.uber.com/ul/?action=setPickup&pickup=my_location":uber,"Uber",true)}${btn(near?"careem://ride":careem,"Careem")}</div>`;
      const mp=masarPos(me.la,me.lo);const inMasar=!near&&mp.in;if(inMasar)log("nav","الضيف داخل وجهة مسار (المدخل الغربي)","ممر المشاة إلى الحرم نحو "+mp.walkKm+" كم");
      const secMasar=inMasar?`<div class="sec">${en?"You are in Masar Destination, the western gateway:":"أنت في وجهة مسار، المدخل الغربي للحرم:"}</div><div class="steps"><div class="step"><i>🚶</i><span>${en?"The Masar pedestrian walkway leads straight to the Haram, separated from traffic with underpasses: about "+mp.walkKm+" km, "+walk(mp.walkKm*1000)+" min on foot.":"ممر مشاة مسار يوصلك إلى المسجد الحرام مباشرة، مفصول عن السيارات بممرات سفلية: نحو "+AR2(mp.walkKm)+" كم، "+AR2(walk(mp.walkKm*1000))+" دقيقة مشيا."} ${btn("https://www.google.com/maps/dir/?api=1&origin="+me.la+","+me.lo+"&destination="+ca+","+co+"&travelmode=walking",en?"Walk the corridor":"امش على الممر",true)}</span></div></div><div style="font-size:.78rem;color:var(--muted)">${en?"Masar also plans rapid buses, a metro extension and parking along the corridor; the Umm Al-Qura stops below are on this axis. Corridor limits are approximate from the master plan.":"وفي مسار أيضا حافلات نقل سريع وامتداد للمترو ومواقف على المحور، ومحطات أم القرى أدناه على هذا المحور. حدود المنطقة تقريبية من المخطط الرئيسي."}</div>`:"";
      const secs=near?secBus+secRide:inMasar?secMasar+secBus+secCar+secRide:mode==="car"?secCar+secBus+secRide:mode==="ride"?secRide+secBus+secCar:secBus+secCar+secRide;
      const fromMap=input&&input.fromMap?`<div style="font-size:.8rem;color:var(--muted);margin-bottom:6px">${en?"The interactive map covers the mosque and its courtyards; you are "+(km<10?km.toFixed(1):Math.round(km))+" km away, so here is how to get there first.":"الخريطة التفاعلية تغطي المسجد وساحاته، وأنت على بعد "+(km<10?AR2(km.toFixed(1)):AR2(Math.round(km)))+" كم، فهذه طريقة الوصول أولا."}</div>`:"";
      card(head("🚌",en?(near?"Leaving the Haram":"Getting to the Haram"):(near?"المغادرة من المسجد الحرام":"الوصول إلى المسجد الحرام"),(inMasar?(en?"Masar Destination · ":"وجهة مسار · "):"")+(en?(km<10?km.toFixed(1):Math.round(km))+" km from the Kaaba":(km<10?AR2(km.toFixed(1)):AR2(Math.round(km)))+" كم عن الكعبة"))+fromMap+secs+`<div style="font-size:.74rem;color:var(--muted);margin-top:6px">${en?"Stops and parking from the open OpenStreetMap map; distances from your phone's location. No live bus timings.":"المحطات والمواقف من خريطة OpenStreetMap المفتوحة، والمسافات من موقع جوالك. لا مواعيد حية للحافلات."}</div>`,"nav");
